const atanSteps=[step('1. Ayır (1 puan)','1. Separate (1 point)',f(dy,n(1)+plus+y2)+eq+x+dx,'1+y²>0; bu bölme reel bir sabit dalı dışlamaz.','1+y²>0, so no real constant branch is excluded.'),step('2. İntegrali al (1 puan)','2. Integrate (1 point)',fn('arctan',y)+eq+f(x2,n(2))+plus+C,'Sol integral arktanjant, sağ integral x²/2.','The left antiderivative is arctangent; the right is x²/2.'),step('3. Aileyi ve aralığı yaz (1 puan)','3. State family and interval (1 point)',y+eq+fn('tan',f(x2,n(2))+plus+C),'Bir bağlı aralıkta seçilen tanjant dalı kutupları geçmez. C=0 için |x|<√π.','On a connected interval the selected tangent branch cannot cross a pole. For C=0, |x|<√π.'),step('4. Türevle denetle (1 puan)','4. Differentiate (1 point)',prime('y')+eq+x+p(n(1)+plus+y2),'Tanjantın türevi sec²=1+tan²; iç fonksiyonun türevi x.','Use tan′=sec²=1+tan² and the inner derivative x.')];
