const squareSteps=[step('1. Bölmeden önce (2 puan)','1. Before dividing (2 points)',y+eq+n(0),'y=0 hem y′=y² denklemini hem başlangıç koşulunu sağlar.','Zero satisfies both y′=y² and the initial condition.'),step('2. Sıfır olmayan aile (1 puan)','2. Nonzero family (1 point)',minus+f(n(1),y)+eq+x+plus+C,'dy/y²=dx integrali alınır; y=−1/(x+C).','Integrate dy/y²=dx to obtain y=−1/(x+C).'),step('3. Veriyi aileye zorla uydurma (1 puan)','3. Do not force the datum into the family (1 point)',minus+f(n(1),C)+o('≠')+n(0),'Hiçbir sonlu ve tanımlı C, y(0)=0 vermez; y=0 ayrı daldır.','No finite, defined C gives y(0)=0; zero is a separate branch.'),step('4. Tekliği gerekçelendir (1 puan)','4. Justify uniqueness (1 point)',v('f')+eq+y2+o(',')+sub(v('f'),y)+eq+n(2)+y,'f ve fᵧ sürekli. Başlangıç noktası çevresinde yerel teklik teoremi uygulanır.','f and fᵧ are continuous. The local uniqueness theorem applies around the initial point.'),step('5. Sonuç ve aralık (1 puan)','5. Conclusion and interval (1 point)',y+p(x)+eq+n(0),'Bu çözüm bütün reel eksende vardır. Aynı IVP’nin bir noktadan sonra sıfırdan ayrılan dalı olamaz; yerel teklik buna engeldir.','This solution exists on the whole real line. It cannot later leave zero as another branch of the same IVP because local uniqueness prevents that.')];
